namespace ghidra.app.plugin.core.debug.gui.trace;





using docking.action;
using docking.widgets.tab;
using ghidra.app.plugin.core.debug.@event;
using ghidra.app.plugin.core.debug.gui;
using ghidra.app.plugin.core.debug.gui.DebuggerResources;
using ghidra.app.plugin.core.debug.gui.thread;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.debug.api.target;
using ghidra.debug.api.target;
using ghidra.debug.api.tracemgr;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool.annotation;
using ghidra.framework.plugintool.util;
using ghidra.trace.model;
using ghidra.trace.model.time.schedule.TraceSchedule;
using ghidra.util;
using utilities.util;
using utilities.util.SuppressableCallback;

public class DebuggerTraceTabPanel : GTabPanel<Trace>, PluginEventListener, DomainObjectListener, DomainFolderChangeListener {

	private class TargetsChangeListener : TargetPublicationListener {
		/* @Override */
		public void targetPublished(Target target) {
			Swing.runIfSwingOrRunLater(() => refreshTab(target.getTrace()));
		}

		/* @Override */
		public void targetWithdrawn(Target target) {
			Swing.runIfSwingOrRunLater(() => refreshTab(target.getTrace()));
		}
	}

	// @AutoServiceConsumed by method
	DebuggerTargetService targetService;
	/* @AutoServiceConsumed */
	private DebuggerTraceManagerService traceManager;
	/* @SuppressWarnings("unused") */
	private AutoService.Wiring autoServiceWiring;

	private TargetsChangeListener targetsListener = new TargetsChangeListener();

	DockingAction actionCloseTrace;
	DockingAction actionCloseOtherTraces;
	DockingAction actionCloseDeadTraces;
	DockingAction actionCloseAllTraces;

	private SuppressableCallback<Void> cbCoordinateActivation = new();

	public DebuggerTraceTabPanel(Plugin plugin) : base("Trace")
    {
		this.autoServiceWiring = AutoService.wireServicesConsumed(plugin, this);

		PluginTool tool = plugin.getTool();
		tool.addEventListener(typeof(TraceOpenedPluginEvent), this);
		tool.addEventListener(typeof(TraceActivatedPluginEvent), this);
		tool.addEventListener(typeof(TraceClosedPluginEvent), this);
		tool.getProject().getProjectData().addDomainFolderChangeListener(this);

		setNameFunction(this.getNameForTrace);
		setIconFunction(this.getIconForTrace);
		setToolTipFunction(this.getTipForTrace);
		setSelectedTabConsumer(this.traceTabSelected);
		// Cannot use method ref here, since traceManager is still null
		setCloseTabConsumer(t => traceManager.closeTrace(t));

		actionCloseTrace = CloseTraceAction.builderPopup(plugin)
				.withContext(typeof(DebuggerTraceFileActionContext))
				.popupWhen(c => {
					Trace trace = c.getTrace();
					if (trace == null) {
						return false;
					}
					actionCloseTrace.getPopupMenuData()
							.setMenuItemName(CloseTraceAction.NAME_PREFIX + getNameForTrace(trace));
					return true;
				})
				.onAction(c => traceManager.closeTrace(c.getTrace()))
				.buildAndInstall(tool);
		actionCloseAllTraces = CloseAllTracesAction.builderPopup(plugin)
				.withContext(typeof(DebuggerTraceFileActionContext))
				.popupWhen(c => traceManager != null && !traceManager.getOpenTraces().isEmpty())
				.onAction(c => traceManager.closeAllTraces())
				.buildAndInstall(tool);
		actionCloseOtherTraces = CloseOtherTracesAction.builderPopup(plugin)
				.withContext(typeof(DebuggerTraceFileActionContext))
				.popupWhen(c => traceManager != null && traceManager.getOpenTraces().size() > 1 &&
					c.getTrace() != null)
				.onAction(c => traceManager.closeOtherTraces(c.getTrace()))
				.buildAndInstall(tool);
		actionCloseDeadTraces = CloseDeadTracesAction.builderPopup(plugin)
				.withContext(typeof(DebuggerTraceFileActionContext))
				.popupWhen(c => traceManager != null && !traceManager.getOpenTraces().isEmpty() &&
					targetService != null)
				.onAction(c => traceManager.closeDeadTraces())
				.buildAndInstall(tool);
	}

	private string getNameForTrace(Trace trace) {
		string name = DomainObjectDisplayUtils.getTabText(trace);
		DebuggerCoordinates current =
			traceManager == null ? DebuggerCoordinates.NOWHERE : traceManager.getCurrentFor(trace);
		if (current == DebuggerCoordinates.NOWHERE) {
			// NOTE: Could use view's snap and time table's schedule, but not worth it.
			return name + " (?)";
		}
		TimeRadix radix = trace.getTimeManager().getTimeRadix();
		string schedule = current.getTime().toString(radix);
		if (schedule.length() > 15) {
			schedule = "..." + schedule.substring(schedule.length() - 12);
		}
		return name + " (" + schedule + ")";
	}

	private Icon getIconForTrace(Trace trace) {
		if (targetService == null) {
			return null;
		}
		Target target = targetService.getTarget(trace);
		if (target == null || !target.isValid()) {
			return null;
		}
		return DebuggerResources.ICON_RECORD;
	}

	private string getTipForTrace(Trace trace) {
		return DomainObjectDisplayUtils.getToolTip(trace);
	}

	public DebuggerTraceFileActionContext getActionContext(MouseEvent e) {
		if (e == null) {
			return null;
		}
		Trace trace = getValueFor(e);
		if (trace == null) {
			return null;
		}
		return new DebuggerTraceFileActionContext(trace);
	}

	/* @AutoServiceConsumed */
	public void setTargetService(DebuggerTargetService targetService) {
		if (this.targetService != null) {
			this.targetService.removeTargetPublicationListener(targetsListener);
		}
		this.targetService = targetService;
		if (this.targetService != null) {
			this.targetService.addTargetPublicationListener(targetsListener);
		}
	}

	protected void add(Trace trace) {
		addTab(trace);
		trace.removeListener(this);
		trace.addListener(this);
	}

	protected void remove(Trace trace) {
		trace.removeListener(this);
		removeTab(trace);
	}

	/* @Override */
	public void eventSent(PluginEvent @event) {
		if (@event is TraceOpenedPluginEvent evt) {
			using (Suppression supp = cbCoordinateActivation.suppress(null))
{
				add(evt.getTrace());
			}
		}
		else if (@event is TraceActivatedPluginEvent evt) {
			Trace trace = evt.getActiveCoordinates().getTrace();
			using (Suppression supp = cbCoordinateActivation.suppress(null))
{
				selectTab(trace);
				refreshTab(trace);
			}
		}
		else if (@event is TraceClosedPluginEvent evt) {
			Trace trace = evt.getTrace();
			using (Suppression supp = cbCoordinateActivation.suppress(null))
{
				remove(trace);
			}
		}
	}

	/* @Override */
	public void domainObjectChanged(DomainObjectChangedEvent ev) {
		if (ev.getSource() is Trace trace) {
			refreshTab(trace);
		}
	}

	/* @Override */
	public void domainFileRenamed(DomainFile file, string oldName) {
		if (file.getOpenedDomainObject(this) is Trace trace) {
			try {
				refreshTab(trace);
			}
			finally {
				trace.release(this);
			}
		}
	}

	/* @Override */
	public void domainFileObjectOpenedForUpdate(DomainFile file, DomainObject @object) {
		if (@object is Trace trace) {
			refreshTab(trace);
		}
	}

	private void traceTabSelected(Trace newTrace) {
		cbCoordinateActivation.invoke(() => {
			if (traceManager == null) {
				return;
			}
			traceManager.activateTrace(newTrace);
		});
	}
}
